//! `/api/v1/requests`: the token user's own requests (guides/api.md). Generated by `cargo offrails generate api requests`.
//! Every lookup goes through `request::find_for`, so another user's id is 404; writes need the
//! `write` scope (403).

use axum::{
    Json,
    extract::{Path, State},
    http::StatusCode,
    response::{IntoResponse, Response},
};

use crate::{
    controllers::api::{ApiJson, ApiUser, ErrorBody, InvalidBody, PageInfo},
    error::AppError,
    models::{Page, request, request::RequestParams},
    state::AppState,
    views::requests_json::{RequestBody, RequestInput, RequestJson, RequestsPage},
};

#[utoipa::path(
    get,
    path = "/api/v1/requests",
    tag = "requests",
    security(("bearer" = [])),
    params(
        ("page" = Option<u64>, Query, description = "1-based"),
        ("per" = Option<u64>, Query, description = "1 to 100, default 25")
    ),
    responses((status = 200, body = RequestsPage), (status = 401, body = ErrorBody), (status = 422, body = InvalidBody))
)]
#[tracing::instrument(skip_all)]
pub async fn index(
    State(s): State<AppState>,
    me: ApiUser,
    page: Page,
) -> Result<Json<RequestsPage>, AppError> {
    let (rows, more) = request::all_for(&s.db, &me.user, page).await?;
    Ok(Json(RequestsPage {
        data: rows.iter().map(RequestJson::from).collect(),
        page: PageInfo {
            page: page.number(),
            per: page.per(),
            has_more: more,
        },
    }))
}

#[utoipa::path(
    get,
    path = "/api/v1/requests/{id}",
    tag = "requests",
    security(("bearer" = [])),
    params(("id" = i64, Path)),
    responses((status = 200, body = RequestBody), (status = 401, body = ErrorBody), (status = 404, body = ErrorBody))
)]
#[tracing::instrument(skip_all)]
pub async fn show(
    State(s): State<AppState>,
    me: ApiUser,
    Path(id): Path<i64>,
) -> Result<Json<RequestBody>, AppError> {
    let record = request::find_for(&s.db, &me.user, id).await?;
    Ok(Json(RequestBody {
        data: RequestJson::from(&record),
    }))
}

#[utoipa::path(
    post,
    path = "/api/v1/requests",
    tag = "requests",
    security(("bearer" = [])),
    request_body = RequestInput,
    responses((status = 201, body = RequestBody), (status = 401, body = ErrorBody), (status = 403, body = ErrorBody), (status = 422, body = InvalidBody))
)]
#[tracing::instrument(skip_all)]
pub async fn create(
    State(s): State<AppState>,
    me: ApiUser,
    ApiJson(input): ApiJson<RequestInput>,
) -> Result<Response, AppError> {
    me.require_write()?;
    let new = input
        .onto(RequestParams::default())
        .validate()
        .map_err(AppError::Invalid)?;
    let record = request::create(&s.db, &me.user, new).await?;
    Ok((
        StatusCode::CREATED,
        Json(RequestBody {
            data: RequestJson::from(&record),
        }),
    )
        .into_response())
}

#[utoipa::path(
    patch,
    path = "/api/v1/requests/{id}",
    tag = "requests",
    security(("bearer" = [])),
    params(("id" = i64, Path)),
    request_body = RequestInput,
    responses((status = 200, body = RequestBody), (status = 401, body = ErrorBody), (status = 403, body = ErrorBody), (status = 404, body = ErrorBody), (status = 422, body = InvalidBody))
)]
#[tracing::instrument(skip_all)]
pub async fn update(
    State(s): State<AppState>,
    me: ApiUser,
    Path(id): Path<i64>,
    ApiJson(input): ApiJson<RequestInput>,
) -> Result<Json<RequestBody>, AppError> {
    me.require_write()?;
    let record = request::find_for(&s.db, &me.user, id).await?;
    let new = input
        .onto(RequestParams::from(&record))
        .validate()
        .map_err(AppError::Invalid)?;
    let record = request::update_for(&s.db, &me.user, record, new).await?;
    Ok(Json(RequestBody {
        data: RequestJson::from(&record),
    }))
}

#[utoipa::path(
    delete,
    path = "/api/v1/requests/{id}",
    tag = "requests",
    security(("bearer" = [])),
    params(("id" = i64, Path)),
    responses((status = 204), (status = 401, body = ErrorBody), (status = 403, body = ErrorBody), (status = 404, body = ErrorBody))
)]
#[tracing::instrument(skip_all)]
pub async fn destroy(
    State(s): State<AppState>,
    me: ApiUser,
    Path(id): Path<i64>,
) -> Result<StatusCode, AppError> {
    me.require_write()?;
    let record = request::find_for(&s.db, &me.user, id).await?;
    request::destroy_for(&s.db, &me.user, record).await?;
    Ok(StatusCode::NO_CONTENT)
}
